/*
 * A064279  Number of ordered pairs a,b of elements in the cyclic group C_n
 *          such that the subgroup generated by the pair a,b is a proper
 *          subgroup of C_n.
 * https://oeis.org/A064279
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = n^2 - J_2(n), where J_2(n) = n^2 ∏_{p|n}(1 - 1/p^2)
 * Range:     u8 n <= 15, u16 n <= 419, u32 n <= 801, u64 n <= 9852,
 *            u128 n <= 9852, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computes the sequence A064279 for any n ≥ 1. */
#include <stddef.h>   /* for size_t */

seq_t a(idx_t n)
{
    /* For n < 1 the sequence is undefined. Return 0. */
    if (n < 1)
        return 0;

    /* n² as a seq_t value. */
    seq_t nseq = (seq_t)n;
    seq_t nn   = nseq * nseq;

    /* Start with J₂(n) = n², then multiply by (p² − 1)/p² for each distinct prime p|n. */
    seq_t j = nn;
    uint64_t t = (uint64_t)n;

    /* Handle factor 2 explicitly. */
    if ((t & 1) == 0) {
        /* p = 2 : (p² − 1)/p² = 3/4 */
        j = j * (seq_t)3 / (seq_t)4;
        while ((t & 1) == 0)
            t >>= 1;
    }

    /* Test odd factors up to √t. */
    for (uint64_t p = 3; p * p <= t; p += 2) {
        if (t % p == 0) {
            seq_t pseq = (seq_t)p;
            seq_t p2   = pseq * pseq;          /* p² */
            j = j * (p2 - (seq_t)1) / p2;       /* multiply by (p² − 1)/p² */
            while (t % p == 0)
                t /= p;
        }
    }

    /* Remaining prime factor > 1. */
    if (t > 1) {
        seq_t pseq = (seq_t)t;
        seq_t p2   = pseq * pseq;
        j = j * (p2 - (seq_t)1) / p2;
    }

    return nn - j;  /* a(n) = n² − J₂(n) */
}
